//   - *AuthStepUpRequiredError (403 auth.step-up.required): This operation needs a fresh passkey proof (a WebAuthn
//     step-up) for this action.
//   - *CoreNotFoundError (404 core.not-found): What the path names does not exist, or the caller cannot see it (the
//     same answer for both).
//   - *BillingInvoiceStripeImportedError (409 billing.invoice.stripe-imported): The invoice was imported from
//     Stripe (Myle's own subscriptions): it is managed in Stripe, never written in Myle.
//   - *PaymentAccountDemoError (409 payments.account.demo): A demo organization never reaches Stripe: nothing was
//     done.
//   - *PaymentAccountNotConnectedError (409 payments.account.not-connected): No Stripe account is connected to the
//     organization: connect one first (POST …/payments-account/onboarding).
//   - *PaymentRefundNothingToRefundError (409 payments.refund.nothing-to-refund): No payment of the invoice was
//     collected through Stripe: there is nothing to refund there.
//   - *CoreIdempotencyKeyReusedError (422 core.idempotency-key-reused): This Idempotency-Key was already used for a
//     request with another body.
//   - *CoreBadGatewayError (502 core.bad-gateway): A service Myle depends on refused the operation.
//
// Example:
//
//	org := client.Organization("organization_…")
//	paymentStatus, err := org.Invoices.Refund(ctx, "invoice_…")
//	if err != nil {
//		return err
//	}
//	fmt.Println(paymentStatus)
func (s *InvoicesService) Refund(ctx context.Context, invoiceID string, opts ...RequestOption) (*PaymentStatus, error) {
	path := "/organizations/" + pathEscape(s.organizationID) + "/invoices/" + pathEscape(invoiceID) + "/refund"
	op := &operation{id: "refundInvoice", method: "POST", pathTemplate: "/organizations/{id}/invoices/{invoiceId}/refund", idempotent: true, retrySafe: true}
	return call[PaymentStatus](ctx, s.core, op, path, nil, nil, opts)
}

// GetPaymentStatus — Get an invoice's payment status.
//
// Returns the payment status of an invoice the caller can see: its status (SEPA_PENDING while a debit is on its
// way), what was paid, what remains due, its payments and its last SEPA debit — what the public payment page shows
// its customer, without a token.
//
// GET /organizations/{id}/invoices/{invoiceId}/payment-status · requires INVOICES_LIST.
//
// It answers the payment status.
//
// Errors worth handling (errors.As):
//
//   - *CoreModuleRequiredError (402 core.module-required): The organization's plan or settings lack the module this
//     operation belongs to.
//   - *AuthRightMissingError (403 auth.right.missing): The caller lacks the right this operation requires in this
//     organization.
//   - *CoreNotFoundError (404 core.not-found): What the path names does not exist, or the caller cannot see it (the
//     same answer for both).
//
// Example:
//
//	org := client.Organization("organization_…")
//	paymentStatus, err := org.Invoices.GetPaymentStatus(ctx, "invoice_…")
//	if err != nil {
//		return err
//	}
//	fmt.Println(paymentStatus)
func (s *InvoicesService) GetPaymentStatus(ctx context.Context, invoiceID string, opts ...RequestOption) (*PaymentStatus, error) {
	path := "/organizations/" + pathEscape(s.organizationID) + "/invoices/" + pathEscape(invoiceID) + "/payment-status"
	op := &operation{id: "getInvoicePaymentStatus", method: "GET", pathTemplate: "/organizations/{id}/invoices/{invoiceId}/payment-status", retrySafe: true}
	return call[PaymentStatus](ctx, s.core, op, path, nil, nil, opts)
}
